package com.funfriday.games.logicgrid;
import com.fasterxml.jackson.core.type.TypeReference; import com.fasterxml.jackson.databind.ObjectMapper; import com.funfriday.db.dao.LogicGridDao; import com.funfriday.db.model.LogicGridPuzzle; import com.funfriday.model.*; import com.funfriday.service.GameLogic; import java.util.*; import lombok.*; import org.springframework.stereotype.Component;
@Component @RequiredArgsConstructor public class LogicGridGame implements GameLogic {
 private final LogicGridDao dao; private final ObjectMapper json;
 public GameData<?> initializeData(GameConfiguration raw){try{Long requested=((LogicGridConfiguration)raw).getPuzzleId();LogicGridPuzzle p=dao.active(requested).orElseThrow(()->new IllegalStateException("No published Logic Grid puzzle is available.")); List<String> entities=json.readValue(p.entitiesJson(),new TypeReference<>(){}); List<Map<String,Object>> attributes=json.readValue(p.attributesJson(),new TypeReference<>(){}); List<String> clues=json.readValue(p.cluesJson(),new TypeReference<>(){}); Map<String,Map<String,String>> solution=json.readValue(p.solutionJson(),new TypeReference<>(){}); LogicGridData d=new LogicGridData(p.id(),p.puzzleKey(),p.category(),p.title(),p.story(),entities,attributes,clues,solution);d.setPlayStartsAtMillis(System.currentTimeMillis()+5000);return d;}catch(Exception e){throw new IllegalStateException("Unable to load Logic Grid puzzle",e);}}
 public void processMove(GameAction raw,GameData<?> generic){if(!"LOGIC_GRID_SYNC".equals(raw.getType())&&!"LOGIC_GRID_GIVE_UP".equals(raw.getType()))return;LogicGridData d=(LogicGridData)generic;if(System.currentTimeMillis()<d.getPlayStartsAtMillis())return;if("LOGIC_GRID_GIVE_UP".equals(raw.getType())){PlayerStats stats=d.getScoreBoard().get(raw.getPlayerId());if(stats!=null)stats.setStatus(PlayerStatus.GIVEN_UP);return;}Map<String,Map<String,String>> submitted=((LogicGridAction)raw).getAnswers();if(submitted==null)return;Map<String,Map<String,String>> clean=new HashMap<>();Set<String> entitySet=new HashSet<>(d.getEntities());Set<String> keys=new HashSet<>();for(Map<String,Object>a:d.getAttributes())keys.add(String.valueOf(a.get("key")));for(var e:submitted.entrySet())if(entitySet.contains(e.getKey())){Map<String,String> row=new HashMap<>();for(var v:e.getValue().entrySet())if(keys.contains(v.getKey())&&v.getValue()!=null)row.put(v.getKey(),v.getValue().trim());clean.put(e.getKey(),row);}d.getPlayerAnswers().put(raw.getPlayerId(),clean);}
 public void updateStats(PlayerStats raw,GameData<?> generic){LogicGridPlayerStats s=(LogicGridPlayerStats)raw;LogicGridData d=(LogicGridData)generic;Map<String,Map<String,String>> answers=d.getPlayerAnswers().get(s.getPlayerId());if(answers==null)return;int total=0,correct=0;boolean allFilled=true;for(String entity:d.getEntities())for(Map<String,Object>a:d.getAttributes()){String key=String.valueOf(a.get("key"));String submitted=answers.getOrDefault(entity,Map.of()).get(key);total++;if(submitted==null||submitted.isBlank())allFilled=false;if(Objects.equals(d.getSolution().getOrDefault(entity,Map.of()).get(key),submitted))correct++;}s.setValuesSolved(correct);s.setScore(correct);s.setProgress(total==0?0:correct*100.0/total);s.setTotalTimeMillis(Math.max(0,System.currentTimeMillis()-d.getPlayStartsAtMillis()));boolean incorrectComplete=total>0&&allFilled&&correct!=total;d.getPlayerIncorrectSubmissions().put(s.getPlayerId(),incorrectComplete);if(total>0&&allFilled&&correct==total)s.setStatus(PlayerStatus.COMPLETED);}
 public boolean isGameOver(GameData<?> d){return d.getScoreBoard().values().stream().allMatch(s->s.getStatus()==PlayerStatus.COMPLETED||s.getStatus()==PlayerStatus.GIVEN_UP);}
 public PlayerStats createInitialStats(GamePlayer p,boolean host){return new LogicGridPlayerStats(p,host);} public GameConfiguration parseConfiguration(Map<String,Object> p){Object id=p.get("puzzleId");return new LogicGridConfiguration(id instanceof Number n?n.longValue():id instanceof String s&&s.matches("\\d+")?Long.parseLong(s):null);}
}
